/* Conditions extracted verbatim from https://datracker.strathfield.nsw.gov.au/document/download?key=5NNtrmGbC0s=&fileName=DA2025 157 1 - 69 Homebush Road STRATHFIELD - Notice of Determination - Approval.PDF (conditions-extractor-2026-08-16) — export-conditions-2026-08-16. Do not hand-edit. */
registerRefData('nsw-cond-n-2031',{"id":2031,"pan":null,"ref":"10.2025.157.1","address":"69 Homebush Rd, Strathfield 2135 NSW","description":"demolition of existing structures, removal of trees and the construction of two storey dwelling house with basement, outbuilding, front fence and associated landscape works.","outcome":"approved","outcome_raw":"Approved - Delegation","outcome_source":"tracker","determined":"2026-03-18","notice_url":"https://datracker.strathfield.nsw.gov.au/document/download?key=5NNtrmGbC0s=&fileName=DA2025 157 1 - 69 Homebush Road STRATHFIELD - Notice of Determination - Approval.PDF","sha256":"7be81ed27ec0335ed349261757fa76c6e1e6cbccdf7f55f0151c15fde7d40070","pages":29,"layout":"numbered","n":70,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/2031.js","source_page":"https://datracker.strathfield.nsw.gov.au/Application/ApplicationDetails/010.2025.00000157.001","lga":"STRATHFIELD","conditions":[{"label":"1","code":null,"number":"1","title":"Shoring and adequacy of adjoining property","text":"1. This section applies to a development consent for development that\ninvolves excavation that extends below the level of the base of the footings\nof a building, structure or work on adjoining land, including a structure or\nwork in a road or rail corridor.\n2. It is a condition of the development consent that the person having the\nbenefit of the development consent must, at the person’s own expense-\na. protect and support the building, structure or work on adjoining\nland from possible damage from the excavation, and\nb. if necessary, underpin the building, structure or work on adjoining\nland to prevent damage from the excavation.\n3. This section does not apply if-\na. the person having the benefit of the development consent owns the\nadjoining land, or\nb. the owner of the adjoining land gives written consent to the\ncondition not applying.","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"Compliance with Building Code of Australia and insurance requirements","text":"under Home Building Act 1989\n1. It is a condition of a development consent for development that involves\nbuilding work that the work must be carried out in accordance with the\nrequirements of the Building Code of Australia.\n2. It is a condition of a development consent for development that involves\nresidential building work for which a contract of insurance is required under\nthe Home Building Act 1989, Part 6 that a contract of insurance is in force\nbefore building work authorised to be carried out by the consent\ncommences.\n3. It is a condition of a development consent for a temporary structure used as\nan entertainment venue that the temporary structure must comply with\nPart B1 and NSW Part H102 in Volume 1 of the Building Code of Australia.\n4. In subsection (1), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for the construction certificate was made.\n5. In subsection (3), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for development consent was made.\n6. This section does not apply-\na. to the extent to which an exemption from a provision of the Building\nCode of Australia or a fire safety standard is in force under\nthe Environmental Planning and Assessment (Development\nCertification and Fire Safety) Regulation 2021, or\nb. to the erection of a temporary building, other than a temporary\nstructure to which subsection (3) applies.","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"Erection of signs","text":"1. This section applies to a development consent for development involving\nbuilding work, subdivision work or demolition work.\n2. It is a condition of the development consent that a sign must be erected in a\nprominent position on a site on which building work, subdivision work or\ndemolition work is being carried out-\na. showing the name, address and telephone number of the principal\ncertifier for the work, and\nb. showing the name of the principal contractor, if any, for the building\nwork and a telephone number on which the principal contractor\nmay be contacted outside working hours, and\nc. stating that unauthorised entry to the work site is prohibited.\n3. The sign must be-\na. maintained while the building work, subdivision work or demolition\nwork is being carried out, and\nb. removed when the work has been completed.\n4. This section does not apply in relation to-\na. building work, subdivision work or demolition work carried out\ninside an existing building, if the work does not affect the external\nwalls of the building, or\nb. Crown building work certified to comply with the Building Code of\nAustralia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"Fulfilment of BASIX commitments","text":"It is a condition of a development consent for the following that each\ncommitment listed in a relevant BASIX certificate is fulfilled-\n1. BASIX development,\nBASIX optional development, if the development application was accompanied\nby a BASIX certificate.","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"Notification of Home Building Act 1989 requirements","text":"1. This section applies to a development consent for development involving\nresidential building work if the principal certifier is not the council.\n2. It is a condition of the development consent that residential building work\nmust not be carried out unless the principal certifier for the development to\nwhich the work relates has given the council written notice of the\nfollowing-\na. for work that requires a principal contractor to be appointed-\ni. the name and licence number of the principal contractor,\nand\nii. the name of the insurer of the work under the Home\nBuilding Act 1989, Part 6,\nb. for work to be carried out by an owner-builder-\ni. the name of the owner-builder, and\nii. if the owner-builder is required to hold an owner-builder\npermit under the Home Building Act 1989-the number of\nthe owner-builder permit.\n3. If the information notified under subsection (2) is no longer correct, it is a\ncondition of the development consent that further work must not be carried\nout unless the principal certifier has given the council written notice of the\nupdated information.\n4. This section does not apply in relation to Crown building work certified to\ncomply with the Building Code of Australia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":4},{"label":"6","code":null,"number":"6","title":"","text":"Approved plans and supporting documentation.\nDevelopment must be carried out in accordance with the following approved\nplans and documents, except where the conditions of this consent expressly\nrequire otherwise.\nApproved Plans\nDescription Reference\nNo.\nDate Revis\nion\nPrepared By\nDemolition Plan Dwg No.\n25474-010\n13 February\n2026\nC ES Design\nProposed Site\nPlan\nDwg No.\n25474-011\n13 February\n2026\nC ES Design\nProposed\nBasement Plan\nDwg No.\n25474-100\n13 February\n2026\nC ES Design\nProposed\nGround Floor\nPlan\nDwg No.\n25474-101\n13 February\n2026\nC ES Design\nProposed First\nFloor Plan\nDwg No.\n25474-102\n13 February\n2026\nC ES Design\nProposed Roof\nPlan\nDwg No.\n25474-103\n13 February\n2026\nC ES Design\nEast and South\nElevation\nDwg No.\n25474-300\n13 February\n2026\nC ES Design\nWest and North\nElevation\nDwg No.\n25474-301\n13 February\n2026\nC ES Design\nSection View A Dwg No.\n25474-310\n13 February\n2026\nC ES Design\nSection View B Dwg No.\n25474-311\n13 February\n2026\nC ES Design\nOutbuilding\nDrawings\nDwg No.\n25474-312\n13 February\n2026\nC ES Design\nSchedule of\nColours and\nFinishes\nDwg No.\n25474-320\n13 February\n2026\nC ES Design\nFront Fence\nDetails\nDwg No.\n25474-600\n13 February\n2026\nC ES Design\nDriveway\nDetails\nDwg No.\n25474-620\n13 February\n2026\nC ES Design\nBasix\nCommitments\nDwg No.\n25474-942\n13 February\n2026\nC ES Design\nLandscape Plan\n& Landscape\nDetails\nJob No.\n20250926,\nLA-01 & LA-\n02 All dated 3\nNovember\n2025\nAll\nIssue\nC\nGround Ink\nStormwater\nLayout Plan,\nBasement Floor\nPlan, Notes &\nDetails\nStormwater\nLayout Plan,\nGround Floor\nPlan, Notes &\nDetails (1/2)\nStormwater\nLayout Plan,\nGround Floor\nPlan, Notes &\nDetails (2/2)\nStormwater\nLayout Plan,\nFirst Floor &\nRoof Plan,\nNotes & Details\n(2/2)\nAll Project\nNo.\nSW25406,\nDrawing\nNos.\nSW010,\nSW020,\nSW021,\nSW030,\nAll 8\nFebruary\n2026\nAll\nRevisi\non D\nCapital Engineering\nConsultants\nStormwater\nLayout Plan,\nErosion &\nSediment\nControl Plan,\nNotes & Details\nER001\nApproved Documentation\nDescription Reference\nNo.\nDate Revis\nion\nPrepared By\nBasix Certificate 1816619S 10\nOctober\n2025\n- Noura Al Hazzouri\nWaste\nManagement\nPlan\n- 14\nOctober\n2025\n- ES Engineering\nArboricultural\nImpact\nAssessment and\nTree\nManagement\nPlan\n- 4 October\n2025\nVersi\non 2\nHorticultural Management\nServices\nIn the event of any inconsistency with the approved plans and a condition of this\nconsent, the condition prevails.","stage":"general","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"Infrastructure Development Contributions","text":"Council has identified that the development will be subject to the imposition of\nDevelopment Contributions. In accordance with Council’s relevant\nContributions Plan, the following monetary contributions are required.\nDEVELOPMENT CONTRIBUTIONS\nStrathfield Section 94A Indirect\nDevelopment Contributions Plan 2010\n$19,315.29\nTOTAL CONTRIBUTIONS $19,315.29\nIndexation\nThe above contributions will be indexed at the time of payment to reflect\ninflation, in accordance with the indices provided by the relevant Development\nContributions Plan. Indexation will be based on the CPI of 101.19 used to\ncalculate the above contribution amount.\nPlease email council council@strathfield.nsw.gov.au prior to the payment of\ns7.11 or s7.12 Contributions to confirm the indexed contribution payable and\nthe form of payment that will be accepted by Council.\nTiming of Payment\nThe contribution must be paid and receipted by Council prior to the issue of the\nConstruction Certificate.\nA copy of the current Development Contributions Plans may be viewed on\nCouncil’s website www.strathfield.nsw.gov.au.","stage":"general","stage_basis":"heading","page":7},{"label":"8","code":null,"number":"8","title":"Section 138 Roads Act 1993 & Section 68 Local Government Act 1993","text":"Unless otherwise specified by a condition of this consent, this Development\nConsent does not give any approval to undertake works on public infrastructure.\nSeparate approval is required under Section 138 of the Roads Act 1993 and\nSection 68 of the Local Government Act 1993 for any of the following activities\ncarried out in, on or over a public road (including the footpath) listed below.\nAn application is required to be lodged and approved prior to the commencement\nof any of the following works or activities.\n(a) If any excavation is to be supported by the use of below ground (cable)\nanchors that are constructed under Council’s roadways/footways.\n(b) Swinging or hoisting goods over any part of a public road by means of a lift,\ncrane or the like;\n(c) Establishing a “works zone”;\n(d) Placing or storing materials or equipment;\n(e) Placing or storing waste containers or skip bins;\n(f) Stormwater & ancillary to public infrastructure on private land\n(g) Erecting a structure or carrying out work\nSeparate activity approvals for (a) -(g) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the issue of the\nConstruction Certificate.\n(h) Pumping water from the site into the public road;\n(i) Constructing a vehicular crossing or footpath;\n(j) Digging up or disturbing the surface of a public road (e.g. Opening the road\nfor the purpose of connections to utility providers);\n(k) Stormwater & ancillary works in the road reserve; and\n(l) Pumping concrete from a public road;\nSeparate activity approvals for (h) -(l) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the activities commencing.\nThe relevant Application Forms for these activities can be downloaded from\nCouncil’s website\nwww.strathfield.nsw.gov.au\nFor further information, please contact Council’s Customer Service Centre on (02)\n9748 9999.","stage":"general","stage_basis":"heading","page":8},{"label":"9","code":null,"number":"9","title":"Vehicular Crossing - Minor Development","text":"Constructing a vehicular crossing and footpath requires a separate approval\nunder Section 138 of the Roads Act 1993 prior to the commencement of those\nworks. This approval must be obtained from Council by completing and\nsubmitting a works permit application.\nThe approval for a new or modified vehicular crossing will contain the plans and\nspecifications required to construct the crossing and footpath. These works must\nbe completed prior to the issue of an Occupation Certificate.","stage":"general","stage_basis":"heading","page":8},{"label":"10","code":null,"number":"10","title":"Road Opening Permit","text":"A Road Opening Permit must be obtained from Council, in the case of local or\nregional roads, or from TFNSW in the case of State roads, for every opening of a\npublic reserve to access services including sewer, stormwater drains, water\nmains, gas mains, and telecommunications before the commencement of works\nin the road.","stage":"general","stage_basis":"heading","page":9},{"label":"11","code":null,"number":"11","title":"Demolition Inspection Fees","text":"The owner/applicant is to arrange for Council to carry out pre -commencement\nand post demolition inspections of the site.\ni. The pre -commencement inspection must be carried out by a Council\nOfficer once all site works required as part of this consent have been\ninstalled and prior to any demolition works commencing.\nii. A final, post demolition inspection must be carried out by a Council\nOfficer once all demolition works have been completed to ensure that the\nsite is left in a satisfactory manner and in accordance with the conditions\nof consent.\niii. A total of $700 for the two (2) inspections is to be paid to Council prior to\nthe issue of the construction certificate or any demolition works\ncommencing on site.\nFees are to be paid to Council prior to issue of construction certificate or\ndemolition works commencing.\nFor booking of Inspections - The applicant/owner is to contact Council’s Customer\nService Centre (ph9748 -9999) minimum two (2) days prior to the required\ninspection.","stage":"general","stage_basis":"heading","page":9},{"label":"12","code":null,"number":"12","title":"Silt-arrestor pit","text":"Pit 1, located at the front of site, is to be designed and constructed as a silt-\narrestor pit.","stage":"general","stage_basis":"heading","page":9},{"label":"13","code":null,"number":"13","title":"Pump-Out System Design for Stormwater Disposal","text":"The design of the pump-out system for stormwater disposal will be permitted for\ndrainage of basement areas only, and must be designed in accordance with the\nfollowing criteria:\n(a) The pump system must consist of two pumps, connected in parallel, with\neach pump being capable of emptying the holding tank at the rate equal\nto the rate of inflow for the one -hour duration storm. The holding tank\nmust be capable of holding four hour’s run off from a one-hour duration\nstorm of the 1 in 100 year storm;\n(b) The pump system must be regularly maintained and serviced, every six\n(6) months; and\n(c) Any drainage disposal to the street gutter from a pump system must have\na stilling sump provided at the property line, connected to the street\ngutter by a suitable gravity line.\nDetails and certification of compliance from a suitably qualified professional\nengineer specialising in hydraulic engineering must be provided to the Principal\nCertifier for approval with the Construction Certificate application.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"14","code":null,"number":"14","title":"Geotechnical Report","text":"The applicant must submit a Geotechnical Report, prepared by a suitably qualified\nprofessional engineer specialising in geotechnical engineering. The Geotechnical\nReport must address dilapidation reports, all site works and construction. This is\nto be su bmitted to the Principal Certifier and Council (where Council is not the\nCertifier) before the issue of the Construction Certificate and must include:\n(a) Investigations certifying the stability of the site and specifying the design\nconstraints to be placed on the foundation, any earthworks, stabilization\nworks and any excavations.\n(b) Dilapidation Reports on the adjoining properties including, but not limited to\n71 Homebush Rd, Strathfield prior to any excavation of site works. The\nDilapidation Report must include assessments on, but not limited to, the\ndwellings at those addresses and any external paths, grounds etc. This must\nbe submitted to the Principal Certifier and the adjoining residents as part of\nthe application for the Construction Certificate. Adjoining residents must be\nprovided with the report five (5) working days prior to any works on the site.\n(c) On-site guidance by a vibration specialist during the early part of excavation.\n(d) Measures to minimise vibration damage and loss of support to other\nbuildings. Where possible any excavation into rock is to be carried out with\ntools such as rock saws which reduce vibration to adjoining buildings and\nassociated structures. Where a hydraul ic hammer is to be used within 30\nmetres of any building (other than a path or a fence) the report must detail\nthe maximum size of hammer to be used and provide all reasonable\nrecommendations to manage impacts.\n(e) Sides of the excavation must be piered prior to any excavation occurring to\nreinforce the walls of the excavation to prevent any subsidence to the\nrequired setbacks and neighbouring sites.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"15","code":null,"number":"15","title":"Long Service Levy","text":"Before the issue of the relevant construction certificate the long service levy of\n$4,828.82, as calculated at the date of this consent, must be paid to the Long\nService Corporation of Council under the Building and Construction industry Long\nService Payments Act 1986 , section 34, and evidence of the payment is to be\nprovided to the certifier.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"16","code":null,"number":"16","title":"Payment of security deposits","text":"Before the issue of the relevant construction certificate, the applicant must:\na) make payment of $17,510.00 for a security deposit and $155.00 for\nAdministration Fee to the consent authority, and\nb) if a principal certifier is required to be appointed for the development -\nprovide the principal certifier with written evidence of the payment and the\namount paid.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"17","code":null,"number":"17","title":"Basix Commitments","text":"The approved BASIX Certificate must be submitted to the Principal Certifier with\nthe application for a Construction Certificate.\nAll measures and commitments as detailed in the BASIX Certificate No. 1816619S\nmust be implemented on the plans lodged with the application for the\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"18","code":null,"number":"18","title":"Stormwater System","text":"The submitted stormwater plan has been assessed as a concept plan only. Final\ndetailed plans of the drainage system in accordance with Council’s Stormwater\nManagement Code and AS/NZS 3500.3: 2015 (as amended), prepared by a\nsuitably qualified professional engineer specialising in hydraulic engineering, must\nbe submitted for approval to the Principal Certifier with the Construction\nCertificate.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"19","code":null,"number":"19","title":"Erosion and sediment control plan","text":"Before the issue of a construction certificate, an erosion and sediment control\nplan must be prepared by a suitably qualified person in accordance with the\nfollowing documents and provided to the certifier:\na) Council’s relevant development control plan,\nb) the guidelines set out in the NSW Department of Housing manual ‘Managing\nUrban Stormwater: Soils and Construction Certificate’ (the Blue Book) (as\namended from time to time), and\nc) the ‘Guidelines for Erosion and Sediment Control on Building Sites’\n(Department of Planning, Housing and Infrastructure)\n(dated 2024, as amended from time to time)","stage":"before_cc","stage_basis":"heading","page":11},{"label":"20","code":null,"number":"20","title":"Dial Before Your Dig","text":"The applicant must contact Home | Before You Dig Australia (BYDA) to obtain a\nService Diagram prior to the issuing of the Construction Certificate. The sequence\nnumber obtained from “Dial Before You Dig” must be forwarded to Council’s\nEngineers for their records.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"21","code":null,"number":"21","title":"Structural Details","text":"Engineer’s details for all reinforced concrete work, structural beams, columns &\nother structural members must be prepared by a suitably qualified practising\nStructural Engineer. These details are to be submitted to the Principal Certifier\nfor approval.\nA copy must be forwarded to Council where Council is not the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"22","code":null,"number":"22","title":"Off Street Parking - Compliance with AS2890","text":"All driveways, access ramps, vehicular crossings and car parking spaces must be\ndesigned and constructed in accordance with the current version of Australian\nStandards, AS 2890.1 (for car parking facilities), AS 2890.6 (parking for people with\ndisabilities) and AS 2890.2 (for commercial vehicle facilities).","stage":"before_cc","stage_basis":"heading","page":12},{"label":"23","code":null,"number":"23","title":"Construction Site Management Plan","text":"Before the issue of a construction certificate, a construction site management\nplan must be prepared, and provided to the certifier. The plan must include the\nfollowing matters:\na) The location and materials for protective fencing and hoardings on the\nperimeter of the site;\nb) Provisions for public safety;\nc) Pedestrian and vehicular site access points and construction activity zones;\nd) Details of construction traffic management including:\ni) Proposed truck movements to and from the site;\nii) Estimated frequency of truck movements; and\niii) Measures to ensure pedestrian safety near the site;\ne) Details of bulk earthworks to be carried out;\nf) The location of site storage areas and sheds;\ng) The equipment used to carry out works;\nh) The location of a garbage container with a tight-fitting lid;\ni) Dust, noise and vibration control measures;\nj) The location of temporary toilets;\nk) The protective measures for the preservation of trees on-site and in\nadjoining public areas including measures in accordance with:\ni) AS 4970 - Protection of trees on development sites;\nii) An applicable Development Control Plan;\niii) An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on-site at all times\nwhile work is being carried out","stage":"before_cc","stage_basis":"heading","page":12},{"label":"24","code":null,"number":"24","title":"Waste Management Plan - an approved document of this consent","text":"Before the issue of a construction certificate, a waste management plan for the\ndevelopment must be provided to the certifier.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"25","code":null,"number":"25","title":"Tree Bond","text":"Tree Bond\nA tree bond (calculated in accordance with Council’s adopted Fees and Charges)\nmust be paid to Council, prior to the issue of a Construction Certificate.\nTree\nnumber\nSpecies Name Height Bond Fee\nT1 Waterhousia floribunda Under 5.0\nMetres\n$3,561.00\nThe deposit is required as security against any damage to existing trees to be\nretained on Council’s Road reserve, during works on the site. The applicant must\nbear the cost of all restoration works to Council’s property damaged during the\ncourse of this development.\nA sound protection barrier anchored firmly into the ground 1.8m in height x 2\nmetres clear of the base of the tree at any one point and that the fence is to extend\nup to the back of the kerb and to the edge of the footpath.\nPayment may be accepted in the form of a bank cheque, credit card, or bank\nguarantee. An administration fee applies to all bonds in accordance with Council’s\nadopted Fees and Charges.\nA request for refund of the Tree Bond must be made in writing.\nTree Bonds may be forfeited if a tree is dead, made dangerous or has been\nterminally damaged, or will be held until tree/s have fully recovered from the\nconstruction damage or were replacement/planted trees have become fully\nestablished and are over 6 metres in height.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"26","code":null,"number":"26","title":"Landscape Plans","text":"All landscape works must be carried out in accordance with the approved\nlandscape plans.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"27","code":null,"number":"27","title":"Tree Removal/Pruning Prohibited","text":"The removal or pruning (branches or roots) of any trees on the subject property\n(excluding those approved for removal in these conditions or species on Council’s\nexempt species list), Council’s public footway, public reserves or on neighbouring\nproperties must not be undertaken other than in accordance with the express\nprovisions of this consent.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"28","code":null,"number":"28","title":"Tree Protection and Retention","text":"The following trees are to be protected throughout the course of all demolition and\nconstruction works. Tree protection is to be in place prior to commencement of\ndemolition works.\nTree No. Tree Species Location of Tree TPZ\nT 1 Waterhousia\nfloribunda\nCouncil Verge 2.0 metres\nT 4 Howea forsteriana Neighbouring tree -\nNorthern side boundary\n2.0 metres\nT 5 Acmena smithii\n‘Minor’\nNeighbouring tree -\nNorthern side boundary\n3.0 metres\nT 6 Michelia figo Neighbouring tree -\nNorthern side boundary\n2.4 metres\nT 7 Corymbia citriodora Neighbouring tree -\nNorthern side boundary\n7.2 metres\nT 11 Morus nigra Neighbouring tree - Rear\nboundary\n4.4 metres\nA project arborist (min. Qualification AQF5) is to be engaged throughout the\ndemolition and construction process.\nAll works within Tree TPZ is to be by hand tools only as per the Aboricultural\nMethod Statement of the AIA Report.\nA Project Arborist must be present on -site during the stages of construction\nwhen works are being undertaken that could impact on the tree canopy or root\nzone within the Tree Protection Zone to implement the tree protection measures\nas required.\nNo services shall be installed within the Tree Protection Zone of the tree unless\napproved by Council. Tree protection fencing shall be kept in place during\ndemolition, construction and also have a sign displaying ‘Tree Protection Zone’\nattached to the fence and must also include the name and contact details of the\nProject Arborist.\nWhere the Tree Protection Zone of trees on site or adjoining sites become\ncompromised by any excavation works, the Project Arborist shall be consulted to\nestablish the position of any major roots and determine the necessary measures\nto protect these roots. The recommendations of the Project Arborist shall be\nsubmitted to Council prior to any further demolition or construction works taking\nplace","stage":"before_cc","stage_basis":"heading","page":14},{"label":"29","code":null,"number":"29","title":"Tree Removal & Replacement","text":"Tree removal\nPermission is granted for the removal of the following trees:\nTree No. Tree species Location\nTree 2 Viburnum tinus Front garden\nTree 3 Magnolia x soulangeana Front garden\nTree 8 Camellia japonica Rear garden\nTree 9 Camellia sasanqua Rear garden\nTree 10 Camellia japonica Rear garden\nTree 12 Plumeria acutifolia Rear garden\nNo Permission is granted for the removal of any other trees on site.\nGeneral Tree Removal Requirements\nAll tree removal work must be undertaken by a minimum Certificate 3 (AQF 3)\nqualified Arborist who is currently a member or eligible for membership to\nArboriculture Australia (AA) or the Tree Contractors Association Australia\n(TCAA), to ensure that removal is undertaken in a safe manner and complies\nwith the AS 4373-2007 - Pruning of Amenity Trees and Amenity Tree Industry\nCode of Practice (Safework NSW, August 1998).\nTree Replacement\nAll trees permitted to be removed by this consent must be replaced 1 tree for\neach tree removed by species selected from Council’s Suggested Tree Species List\nand must be able to achieve a minimum mature height of 10 metres\nReplacement trees must be a minimum 75 litre container size. Trees are to meet\nthe requirements of AS 2303: 2018- Tree Stock for Landscape Use. Trees must be\ntrue to type, healthy and vigorous at time of delivery and planting, must be pest\nand disease free, free from injury and wounds and self -supporting; and must be\nmaintained until maturity.\nAll trees must be staked and tied with a minimum of three (3) hardwood stakes.\nTies must be hessian and fixed firmly to the stakes, one tie at half the height of\nthe main stem, others as necessary to stabilise the plant.\nTrees within lawn areas or street verges must have Tree Guard bark protectors\ninstalled around the base of trunks to protect from damage by trimmers and\nmowers.\nRoot deflection barriers having a minimum depth of 600mm are to be installed\nadjacent to all footpaths and driveways.\nSoil conditioner, fertilizer, and moisture retention additives must be applied in\naccordance with manufacturer’s recommendations, and mixed into the backfilling\nsoil after planting tree/s.\nA minimum 75mm depth of organic mulch must be placed around the tree,\nextending to a minimum radius 0.5m from the base of the trunk. Mulch shall be\n‘dished’ around the base of the tree’s trunk.\nDetails demonstrating compliance must be demonstrated to the Principal\nCertifier, prior to the issue of any Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"30","code":null,"number":"30","title":"Street and Reserve Tree Protection and Retention","text":"A protective fence consisting of a fully supported chainmesh fence 1.8 metres\nheight x 2 metres clear of the base of the tree at any one point must be erected\naround the nominated street trees in front of 69 Homebush Road, Strathfield and\nany trees in adjacent reserves and parks if applicable, unless otherwise specified\nin AS4970-2009. The fence is to extend up to the back of the kerb and to the edge\nof the footpath. No services shall be installed within the Tree Protection Zone of\nthe tree unless approved by Council. Tree protection fencing shall be kept in place\nduring demolition, construction and also have a sign displaying ‘Tree Protection\nZone’ attached to the fence and must also include the name and contact details\nof the Project Arborist.\nNo soil, fill, building materials or waste should be placed or disposed of within the\nprotection area.\nTree No. Tree Species Location of Tree\nT 1 Waterhousia floribunda Council Verge\nShould replacement or repair of the public footpath or vehicle crossing within the\nTree Protection Zone area of a street tree be required, Council’s Urban Forest\nSupervisor is to be notified (with minimum 24hrs notice) of the intent to\nundertake the works and is to attend a site inspection after the existing footpath\nhas been lifted but prior to any preparation works for laying of the new path. No\nstreet tree roots are to be cut without the Approval of Council. Failure to comply\nwith this condition may result in the forfeiting of the Tree Bond should the street\ntree’s health or structure be compromised.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"31","code":null,"number":"31","title":"Dilapidation report","text":"Before any site work commences, a dilapidation report must be prepared by a\nsuitably qualified engineer detailing the structural condition of adjoining\nbuildings, structures or works and public land, to the satisfaction of the principal\ncertifier.\nWhere access has not been granted to any adjoining properties to prepare the\ndilapidation report, the report must be based on a survey of what can be\nobserved externally and demonstrate, in writing, to the satisfaction of the\nprincipal certifier that all reasonable steps were taken to obtain access to the\nadjoining properties.\nNo less than 5 days before any site work commences, adjoining building owner(s)\nmust be provided with a copy of the dilapidation report for their property(ies) and\na copy of the report(s) must be provided to council (where council is not the\nprincipal certifier) at the same time.","stage":"before_work","stage_basis":"heading","page":17},{"label":"32","code":null,"number":"32","title":"Dust Control","text":"Where a dust nuisance is likely to occur, suitable screens and barricades must be\nerected during the demolition, excavation and building works. Water sprays must\nbe used on the site to reduce the emission of dust. Screening must consist of a\nminimum 2 metr es height of shade cloth or similar material secured to a chain\nwire fence or the like and must be modified as required should it fail to adequately\ncontrol any dust nuisance.","stage":"before_work","stage_basis":"heading","page":17},{"label":"33","code":null,"number":"33","title":"Demolition & Asbestos","text":"The demolition work must comply with the provisions of Australian Standard\nAS2601:2001 - Demolition of Structures, NSW Work Health & Safety Act 2011 and\nthe NSW Work Health & Safety Regulation 2011 . The work plans required by\nAS2601:2001 must be accompanied by a written statement by a suitably qualified\nperson that the proposals contained in the work plan comply with the safety\nrequirements of the Standard. The work plans and the safety statement must be\nsubmitted to the Principal Certifier prior to the commencement of works.\nFor demolition work which involves the removal of asbestos, the asbestos\nremoval work must be carried out by a licensed asbestos removalist who is\nlicensed to carry out the work in accordance with the NSW Work Health & Safety\nAct 2011 and the NSW Work Health & Safety Regulation 2011 unless specified in\nthe Act or Regulation that a license is not required.\nAll demolition work including the removal of asbestos, must be undertaken in\naccordance with the Demolition Code of Practice (NSW Work Cover July 2015)","stage":"before_work","stage_basis":"heading","page":17},{"label":"34","code":null,"number":"34","title":"Demolition Notification Requirements","text":"The following notification requirements apply to this consent:\n(a) The builder must notify adjoining residents five (5) working days prior to\ndemolition. Such notification will be a clearly written note giving the date\ndemolition will commence, contact details of the builder, licensed asbestos\ndemolisher and the appropri ate regulatory authority. Notification must be\nplaced in the letterbox of every premises (including every residential flat or\nunit, if any) either side and immediately at the rear of the demolition site.\n(b) Five (5) working days prior to demolition, the builder must provide written\nnotification to Council advising of the demolition date, details of the SafeWork\nlicensed asbestos demolisher and the list of residents advised of the\ndemolition.\n(c) On demolition sites where buildings to be demolished contain asbestos, a\nstandard commercially manufactured sign containing the words “DANGER\nASBESTOS REMOVAL IN PROGRESS” measuring not less than 400mm x\n300mm must be erected in a prominent visible position (from street frontage)\non the site. The sign must be erected prior to demolition work commencing\nand will remain in place until such time as all asbestos material has been\nremoved from the site to an approved waste facility.","stage":"before_work","stage_basis":"heading","page":17},{"label":"35","code":null,"number":"35","title":"Demolition Work Involving Asbestos Removal","text":"Work involving bonded asbestos removal work (of an area of more than 10 square\nmetres) or friable asbestos removal work must be undertaken by a person who\ncarries on a business of such removal work in accordance with a licence under\nclause 458 of the Work Health and Safety Regulation 2011","stage":"before_work","stage_basis":"heading","page":18},{"label":"36","code":null,"number":"36","title":"Utility Arrangements","text":"Arrangements must be made with utility authorities in respect to the services\napplied those authorities to the development. The cost associated with the\nprovision or adjustment of services within the road and footway areas will be at\nthe applicant’s expense.","stage":"before_work","stage_basis":"heading","page":18},{"label":"37","code":null,"number":"37","title":"Erosion and sediment controls in place","text":"Before any site work commences, the principal certifier, must be satisfied the\nerosion and sediment controls in the erosion and sediment control plan which\nwas provided to the principal certifier are in place. These controls must remain in\nplace until any bare earth has b een restabilised in accordance with the erosion\nand sediment control plan.","stage":"before_work","stage_basis":"heading","page":18},{"label":"38","code":null,"number":"38","title":"Tree protection measures","text":"Before any site work commences, the principal certifier, or council where a\nprincipal certifier is not required, must be satisfied the measures for tree\nprotection detailed in the construction site management plan are in place.","stage":"before_work","stage_basis":"heading","page":18},{"label":"39","code":null,"number":"39","title":"Soil management","text":"While site work is being carried out, the principal certifier must be satisfied all\nsoil removed from or imported to the site is managed in accordance with the\nfollowing requirements:\na) All excavated material removed from the site must be classified in\naccordance with the EPA’s Waste Classification Guidelines before it is\ndisposed of at an approved waste management facility and the\nclassification and the volume of material removed must be reported to the\nprincipal certifier\nb) All fill material imported to the site must be:\ni) Virgin Excavated Natural Material as defined in Schedule 1 of the\nProtection of the Environment Operations Act 1997, or\nii) a material identified as being subject to a resource recovery exemption\nby the NSW EPA, or\niii) a combination of Virgin Excavated Natural Material as defined in\nSchedule 1 of the Protection of the Environment Operations Act 1997\nand a material identified as being subject to a resource recovery\nexemption by the NSW EPA.","stage":"during_work","stage_basis":"heading","page":19},{"label":"40","code":null,"number":"40","title":"Hours of work","text":"Site work must only be carried out between the following times -\nFor building construction and delivery of machinery and materials from 7:00am\nto 5:00pm on Monday to Saturday (excluding Public Holidays)\nFor demolition, excavation and/or construction works that involve heavy\nmachinery, noisy trades, or the like from 7:00am to 5:00pm on Monday to Friday\n(excluding Public Holidays)\nSite work is not to be carried out outside of these times except where there is an\nemergency, or for urgent work directed by a police officer or a public authority.","stage":"during_work","stage_basis":"heading","page":19},{"label":"41","code":null,"number":"41","title":"Ground Levels and Retaining Walls","text":"The ground levels of the site must not be excavated, raised or filled and retaining\nwalls constructed on the allotment boundary, except where indicated on\napproved plans or approved by Council.","stage":"during_work","stage_basis":"heading","page":19},{"label":"42","code":null,"number":"42","title":"Cost of Work to be Borne by the Applicant","text":"The applicant must pay the cost of all works associated with the construction of\nthe development that occurs on Council property. Care must be taken to protect\nCouncil’s roads, including the made footway, kerbs, etc, and where plant and\nvehicles enter the site, the footway must be protected against damage by deep -\nsectioned timber members laid crosswise, held together by hoop iron straps and\nchamfered at their ends. This construction must be maintained in a state of good\nrepair and condition throughout the course of construction.","stage":"during_work","stage_basis":"heading","page":19},{"label":"43","code":null,"number":"43","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved\nremoval, relocation or reconstruction of infrastructure (including ramps,\nfootpaths, kerb and gutter, light poles, kerb inlet pits, service provider pits, street\ntrees or any other infrastructure in the street footpath area) must be paid as\ndirected by the consent authority.","stage":"during_work","stage_basis":"heading","page":20},{"label":"44","code":null,"number":"44","title":"Obstruction of Road or Footpath","text":"The use of the road or footpath for the storage of any building materials, waste\nmaterials, temporary toilets, waste or skip bins, or any other matter is not\npermitted unless separately approved by Council under Section 138 of the Roads\nAct 1993 and under Section 68 of the Local Government Act 1993 . Penalty\ninfringement Notices may be issued for any offences and severe penalties apply.","stage":"during_work","stage_basis":"heading","page":20},{"label":"45","code":null,"number":"45","title":"Construction Management Plan","text":"The builder must ensure that the approved Construction Traffic Management Plan\nis to be strictly complied with and kept on site at all times during construction\nworks.","stage":"during_work","stage_basis":"heading","page":20},{"label":"46","code":null,"number":"46","title":"Procedure for critical stage inspections","text":"While building work is being carried out, the work must not continue after each\ncritical stage inspection unless the principal certifier is satisfied the work may\nproceed in accordance with this consent and the relevant construction certificate.","stage":"during_work","stage_basis":"heading","page":20},{"label":"47","code":null,"number":"47","title":"Registered Surveyors Report","text":"A report must be submitted to the Principal Certifier at each of the following\napplicable stages of construction:\n(a) Set out before commencing excavation.\n(b) Floor slabs or foundation wall, before formwork or commencing\nbrickwork.\n(c) Completion of Foundation Walls - Before any construction of flooring,\ndetailing the location of the structure relative to adjacent boundaries\nand floor levels relative to the datum shown on the approved plans.\n(d) Completion of Floor Slab Formwork - Before pouring of concrete/walls\nconstruction, detailing the location of the structure relative to adjacent\nboundaries and floor levels relative to the datum shown on the approved\nplans. In multi -storey buildings a furt her survey must be provided at\neach subsequent storey.\n(e) Completion of any Pool Formwork - Before concreting of pool shell,\ndetailing the location of the pool relative to the adjacent boundaries and\nits height relative to the datum shown on the approved plans.\n(f) Completion of any Roof Framing - Before roof covered detailing\neaves/gutter setback from boundaries.\n(g) Completion of all Work - Detailing the location of the structure (including\neaves/gutters) relative to adjacent boundaries and its height relative to\nthe datum shown on the approved plans. A final Check Survey must\nindicate the reduced level of the main ridge.\nWork must not proceed beyond each stage until the Principal Certifier is satisfied\nthat the height and location of the building is proceeding in accordance with the\napproved plans.","stage":"during_work","stage_basis":"heading","page":20},{"label":"48","code":null,"number":"48","title":"Implementation of the site management plans while site work is being carried","text":"out:\na) the measures required by the construction site management plan and the\nerosion and sediment control plan (plans) must be implemented at all\ntimes, and\nb) a copy of these plans must be kept on site at all times and made available\nto council officers upon request.","stage":"during_work","stage_basis":"heading","page":21},{"label":"49","code":null,"number":"49","title":"Tree Removal on Private Land","text":"The trees identified as ‘to be removed/pruned’ on the approved plans or by\nconditions of this consent must be removed in accordance with AS4373 -2007 and\nthe Amenity Tree Industry Code of Practice (SafeWork NSW, August 1998).","stage":"during_work","stage_basis":"heading","page":21},{"label":"50","code":null,"number":"50","title":"Tree protection during work","text":"While site work is being carried out, all required tree protection measures must\nbe maintained in good condition in accordance with:\na) the construction site management plan required under this consent,\nb) the relevant requirements of AS 4970 Protection of trees on development\nsites,\nc) section(s) of council’s relevant development control plan (in force as at the\ndate of determination of this consent) and\nd) any arborist’s report approved under this consent.\nThis includes maintaining adequate soil grades and ensuring all machinery,\nbuilders refuse, spoil and materials remain outside tree protection zones.","stage":"during_work","stage_basis":"heading","page":21},{"label":"51","code":null,"number":"51","title":"Waste management","text":"While site work is being carried out:\na) all waste management must be undertaken in accordance with the waste\nmanagement plan, and\nb) upon disposal of waste, records of the disposal must be compiled and\nprovided to the Certifier, or Council where a certifier is not required,\ndetailing the following:\ni) The contact details of the person(s) who removed the waste\nii) The waste carrier vehicle registration\niii) The date and time of waste collection\niv) A description of the waste (type of waste and estimated quantity)\nand whether the waste is to be reused, recycled or go to landfill\nv) The address of the disposal location(s) where the waste was taken\nvi) The corresponding tip docket/receipt from the site(s) to which the\nwaste is transferred, noting date and time of delivery, description\n(type and quantity) of waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order\nor Exemption, records in relation to that Order or Exemption must be\nmaintained and provided to the principal certifier and council.","stage":"during_work","stage_basis":"heading","page":22},{"label":"52","code":null,"number":"52","title":"Connection to the Network","text":"Where works within the road reserve are to be carried out by the developer, a\nRoad Opening Permit must be obtained from Council before the\ncommencement of any work.","stage":"during_work","stage_basis":"heading","page":22},{"label":"53","code":null,"number":"53","title":"Electricity Supply to Development","text":"The electricity supply to the Development must be underground.","stage":"during_work","stage_basis":"heading","page":22},{"label":"54","code":null,"number":"54","title":"Restriction to User and Positive Covenant for Stormwater Management System","text":"Prior to the issue of any Occupation Certificate, the applicant must register a\nPositive Covenant and a Restriction as to User under section 88E and or section\n88B of the Conveyancing Act as appropriate in favour of Council, e nsuring the\nongoing retention, maintenance and operation of the stormwater facility (on-site\ndetention, pump-out, charged lines, water sensitive urban design, surface flow\npath, finished pavement and ground levels etc.).\nWhere any drainage line or service conduit is to traverse any property other than\nthat which it serves, an appropriate easement will be required. In this case, the\napplicant must register an easement no less than 1200mm wide over the\nproposed drainage line or service concurrently with any subdivision registration.\nThe wording on the 88E and or 88B Instrument is to make reference to the Council\nfile where the Construction plans and the Work As Executed (as built), plans are\nheld. Typical wording can be obtained from Council's Specification for the\nManagement of Stormwater document.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"55","code":null,"number":"55","title":"Maintenance Schedule - On-site Stormwater Management","text":"A Maintenance Schedule for the proposed on -site stormwater management\nmeasures must be prepared by a suitably qualified professional hydraulic\nengineer and submitted to Council. The Maintenance Schedule must outline the\nrequired maintenance works, how and when these will be done and who will be\ncarrying out these maintenance works.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"56","code":null,"number":"56","title":"Stormwater Certification of the Constructed Drainage Works (Minor)","text":"The constructed stormwater system must be certified by a suitably qualified\nperson, in accordance with Council’s Stormwater Management Code, prior to the\nissue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"57","code":null,"number":"57","title":"Post-construction dilapidation report","text":"Before the issue of an occupation certificate a post- construction dilapidation\nreport must be prepared by a suitably qualified engineer, to the satisfaction of\nthe principal certifier, detailing whether:\na) after comparing the pre-construction dilapidation report to the post-\nconstruction dilapidation report required under this condition, there has\nbeen any structural damage to any adjoining buildings; and\nb) where there has been structural damage to any adjoining buildings, that it\nis a result of the work approved under this development consent, and\na copy of the post-construction dilapidation report must be provided to council\n(where council is not the principal certifier or a principal certifier is not required)\nand to the relevant adjoining property owner(s).","stage":"before_oc","stage_basis":"heading","page":23},{"label":"58","code":null,"number":"58","title":"BASIX Certificate","text":"All energy efficiency measures as detailed in the approved BASIX Certificate in the\nplans approved with the Development Consent, must be implemented before the\nissue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"59","code":null,"number":"59","title":"Completion of Landscape Works and Tree Works","text":"Before the issue of an Occupation Certificate, the principal certifier must be\nsatisfied all landscape and tree-works have been completed in accordance with\napproved plans and documents and any relevant conditions of this consent.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"60","code":null,"number":"60","title":"Minor Development","text":"Internal driveways and parking spaces must be adequately paved with concrete\nor bitumen, or interlocking pavers to provide a dust-free surface.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"61","code":null,"number":"61","title":"Vehicular Crossing - Minor Development","text":"The vehicular crossing and footpath works must be constructed by a private\ncontractor at the expense of the applicant, in accordance with the Works Permit\nApproval issued by Council’s Engineering Design Services and in accordance with\nCouncil’s Driveway Specifications.\nAny existing vehicular crossing and laybacks which are redundant must be\nremoved. The kerb and gutter, any other footpath and turf areas must be restored\nat the expense of the applicant and in accordance with Council’s Driveway\nSpecifications.\nThe work must be completed before the issue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"62","code":null,"number":"62","title":"Release of securities","text":"When Council receives an occupation certificate, an application may be lodged to\nrelease the securities held in accordance with council policy.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"63","code":null,"number":"63","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":24},{"label":"64","code":null,"number":"64","title":"Removal of waste upon completion","text":"","stage":"before_oc","stage_basis":"heading","page":25},{"label":"65","code":null,"number":"65","title":"Electricity Supply","text":"Prior to the issue of any Occupation Certificate, evidence must be provided\ndemonstrating that the development has been connected to the Ausgrid network.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"66","code":null,"number":"66","title":"Completion of public utility services","text":"Before the issue of the relevant occupation certificate, confirmation must be\nobtained from the relevant authority that any adjustment or augmentation of any\npublic utility services including gas, water, sewer, electricity, street lighting and\ntelecommunications, required as a result of the development, have been\ncompleted and this confirmation must be provided to the principal certifier.","stage":"before_oc","stage_basis":"heading","page":25},{"label":"67","code":null,"number":"67","title":"Maintenance of wastewater and stormwater treatment device","text":"During occupation and ongoing use of the building, all wastewater and\nstormwater treatment devices (including drainage systems, sumps and traps, and\non-site detention) must be regularly maintained to remain effective and in\naccordance with any positive covenant (if applicable).","stage":"ongoing","stage_basis":"heading","page":26},{"label":"68","code":null,"number":"68","title":"Entering and Exiting of Vehicles","text":"All vehicles must enter and exit the premises in a forward direction.","stage":"ongoing","stage_basis":"heading","page":26},{"label":"69","code":null,"number":"69","title":"Maintenance of Landscaping","text":"All trees and plants forming part of the landscaping must be maintained.\nMaintenance includes watering, weeding, removal of rubbish from tree bases,\nfertilising, pest and disease control, replacement of dead or dying plants and any\nother operations required to maintain healthy trees, plants and turfed areas.","stage":"ongoing","stage_basis":"heading","page":26},{"label":"70","code":null,"number":"70","title":"Greywater System","text":"In order to conserve and re -use water, Council encourages all development for\nnew dwellings to incorporate a greywater reuse system. The system can\nincorporate a greywater diversion device or a domestic greywater treatment\nsystem. Any system installed must ensure that it complies with the Plumbing Code\nof Australia. Th system must be maintained at all times and must not result in any\nadverse amenity impacts on the subject premises and surrounding properties.","stage":"ongoing","stage_basis":"heading","page":26}]});
